import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useIntl } from 'react-intl';
import PropTypes from 'prop-types';
import { getVulnsCountBySeverity } from 'Screens/Contextualization/Dashboard/actions/Actions';
import {
  addFilter,
  removeFilter,
  setFilter,
  storeDashboardFilter
} from 'store/Filters/actions';
import {
  CLOSED_FILTERS,
  CONFIRMED_FLAG_FILTERS,
  DASHBOARD_FILTERS
} from 'store/Filters/constants';
import {
  isFilteringBy,
  selectStoredDashboardFilter
} from 'store/Filters/selectors';
import { selectCurrentWorkspace } from 'store/Faraday/selectors';
import { redirect } from 'store/Router/actions';
import SpinnerComponent from 'Common/Components/SpinnerContainer';
import formatNumber from 'Common/Functions/FormatNumber';
import { STEP_VALUES } from 'Common/Components/SeverityRange/constants';
import { formatSeverityFooter } from '../common/formatWidgetMessages';
import Checkbox from 'Common/Components/Checkbox';
import {
  Wrapper,
  Empty,
  ContentWrapper,
  SeverityBar,
  SeverityBadge,
  SeverityLabel,
  SeverityCount,
  BarContainer,
  BarFill,
  Footer,
  FooterText,
  SeverityIcon,
  TotalCountText,
  TotalCountNumber,
  TotalsContainer,
  FilterDropdownWrapper,
  FilterDropdownSelector,
  FilterDropdownOption
} from './styled';
import { FilterButton } from '../common/styled';
import TitleWrapper from '../components/TitleWrapper';

// Only patches the two shorthands STEP_VALUES.parsedSeverity uses ('med', 'info');
// any other severity falls through via the `?? severity` fallback in handleSeverityClick.
// If a new shorthand is ever added to STEP_VALUES, it must be added here too.
const SEVERITY_FILTER_VALUE = {
  med: 'medium',
  info: 'informational'
};

const BySeverity = ({ variant = 'horizontal' }) => {
  const dispatch = useDispatch();
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const dropdownRef = useRef(null);

  const { confirmed } = CONFIRMED_FLAG_FILTERS;
  const { closed } = CLOSED_FILTERS;

  const isFilteringByConfirm = useSelector((state) =>
    isFilteringBy(state, 'vulns', confirmed)
  );
  const isFilteringByClosed = useSelector((state) =>
    isFilteringBy(state, 'vulns', closed)
  );
  const storedFilters = useSelector(selectStoredDashboardFilter);

  const vulnCountBySeverity = useSelector(
    (state) => state.dashboard?.vulnCountBySeverity ?? {}
  );
  const isFetching = useSelector(
    (state) => state.dashboard?.loadingState?.vulnCountBySeverity ?? false
  );
  const workspaceSelected = useSelector((state) =>
    selectCurrentWorkspace(state)
  );
  const intl = useIntl();
  const translations = useMemo(
    () => ({
      title: intl.formatMessage({ id: 'dashboard.widgets.bySeverity.title' }),
      addFilter: intl.formatMessage({
        id: 'dashboard.widgets.bySeverity.addFilter'
      }),
      empty: intl.formatMessage({ id: 'dashboard.widgets.bySeverity.empty' }),
      findingsDetected: intl.formatMessage({
        id: 'dashboard.widgets.bySeverity.findingsDetected'
      }),
      highRisk: intl.formatMessage({ id: 'dashboard.widgets.high_risk' }),
      mediumLow: intl.formatMessage({
        id: 'dashboard.widgets.bySeverity.mediumLow'
      }),
      unclassified: intl.formatMessage({
        id: 'dashboard.widgets.bySeverity.unclassified'
      }),
      confirmed: intl.formatMessage({
        id: 'dashboard.widgets.bySeverity.filter.confirmed'
      }),
      notClosed: intl.formatMessage({
        id: 'dashboard.widgets.bySeverity.filter.notClosed'
      })
    }),
    [intl]
  );

  useEffect(() => {
    if (storedFilters.confirmed) dispatch(addFilter('vulns', confirmed));
    if (storedFilters.closed) dispatch(addFilter('vulns', closed));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const filterParams = useMemo(() => {
    const parts = [];
    if (isFilteringByConfirm) parts.push('confirmed=true');
    if (isFilteringByClosed) parts.push('only_opened=true');
    return parts.length ? `&${parts.join('&')}` : '';
  }, [isFilteringByConfirm, isFilteringByClosed]);

  useEffect(() => {
    dispatch(getVulnsCountBySeverity(filterParams));
  }, [dispatch, filterParams, workspaceSelected]);

  useEffect(() => {
    const handleClickOutside = (e) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
        setDropdownOpen(false);
      }
    };
    if (dropdownOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [dropdownOpen]);

  const confirmedFilterToggle = () => {
    dispatch(storeDashboardFilter('confirmed', !isFilteringByConfirm));
    if (isFilteringByConfirm) dispatch(removeFilter('vulns', confirmed));
    else dispatch(addFilter('vulns', confirmed));
  };

  const closedFilterToggle = () => {
    dispatch(storeDashboardFilter('closed', !isFilteringByClosed));
    if (isFilteringByClosed) dispatch(removeFilter('vulns', closed));
    else dispatch(addFilter('vulns', closed));
  };

  const filterLabel = useMemo(() => {
    if (isFilteringByConfirm && isFilteringByClosed) {
      return `${translations.confirmed}, ${translations.notClosed}`;
    }
    if (isFilteringByConfirm) return translations.confirmed;
    if (isFilteringByClosed) return translations.notClosed;
    return translations.addFilter;
  }, [isFilteringByConfirm, isFilteringByClosed, translations]);

  const critical = vulnCountBySeverity?.critical ?? 0;
  const high = vulnCountBySeverity?.high ?? 0;
  const med = vulnCountBySeverity?.medium ?? 0;
  const low = vulnCountBySeverity?.low ?? 0;
  const info = vulnCountBySeverity?.informational ?? 0;
  const unclassified = vulnCountBySeverity?.unclassified ?? 0;

  const total = critical + high + med + low + info + unclassified;

  const valueMap = { critical, high, med, low, info, unclassified };

  const severities = [...STEP_VALUES].reverse().map((step) => ({
    id: step.parsedSeverity,
    label: step.label.charAt(0) + step.label.slice(1).toLowerCase(),
    value: valueMap[step.parsedSeverity] ?? 0,
    color: step.color
  }));

  const handleSeverityClick = (severity) => {
    const filterValue = SEVERITY_FILTER_VALUE[severity] ?? severity;

    dispatch(
      setFilter(
        'vulns',
        DASHBOARD_FILTERS.vulnerabilitiesBySeverity(filterValue)
      )
    );
    if (isFilteringByConfirm) dispatch(addFilter('vulns', confirmed));
    if (isFilteringByClosed) dispatch(addFilter('vulns', closed));
    dispatch(redirect(`/manage/${workspaceSelected}`));
  };

  const { leftText, rightText } = formatSeverityFooter({
    critical,
    high,
    med,
    low,
    unclassified,
    translations
  });

  if (isFetching) return <SpinnerComponent height="250px" />;

  return (
    <Wrapper>
      <TitleWrapper
        title={ translations.title }
        info={
          <FilterDropdownWrapper ref={ dropdownRef }>
            <FilterButton
              onClick={ () => setDropdownOpen((o) => !o) }
              $active={ isFilteringByConfirm || isFilteringByClosed }
            >
              {filterLabel}
            </FilterButton>
            {dropdownOpen && (
              <FilterDropdownSelector>
                <FilterDropdownOption onClick={ confirmedFilterToggle }>
                  <Checkbox state={ isFilteringByConfirm } />
                  {translations.confirmed}
                </FilterDropdownOption>
                <FilterDropdownOption onClick={ closedFilterToggle }>
                  <Checkbox state={ isFilteringByClosed } />
                  {translations.notClosed}
                </FilterDropdownOption>
              </FilterDropdownSelector>
            )}
          </FilterDropdownWrapper>
        }
        icon={ <SeverityIcon /> }
      />
      {total === 0
        ? (
        <Empty>{translations.empty}</Empty>
          )
        : (
        <>
          <TotalsContainer>
            <TotalCountNumber>{formatNumber(total)}</TotalCountNumber>
            <TotalCountText> {translations.findingsDetected}</TotalCountText>
          </TotalsContainer>

          <ContentWrapper $variant={ variant }>
            {severities.map((severity) => (
              <SeverityBar
                key={ severity.id }
                onClick={ () => handleSeverityClick(severity.id) }
                $variant={ variant }
                $color={ severity.color }
              >
                <SeverityBadge color={ severity.color }>
                  {severity.label.charAt(0)}
                </SeverityBadge>
                {variant === 'vertical'
                  ? (
                  <>
                    <SeverityCount $variant={ variant }>
                      {formatNumber(severity.value)}
                    </SeverityCount>
                    <SeverityLabel $variant={ variant }>
                      {severity.label}
                    </SeverityLabel>
                  </>
                    )
                  : (
                  <>
                    <SeverityLabel $variant={ variant }>
                      {severity.label}
                    </SeverityLabel>
                    <BarContainer $variant={ variant }>
                      <BarFill
                        color={ severity.color }
                        width={ total > 0 ? (severity.value / total) * 100 : 0 }
                      />
                    </BarContainer>
                    <SeverityCount $variant={ variant }>
                      {formatNumber(severity.value)}
                    </SeverityCount>
                  </>
                    )}
              </SeverityBar>
            ))}
          </ContentWrapper>
          {variant !== 'vertical' && (
            <Footer>
              <FooterText>{leftText}</FooterText>
              <FooterText>{rightText}</FooterText>
            </Footer>
          )}
        </>
          )}
    </Wrapper>
  );
};

BySeverity.propTypes = {
  variant: PropTypes.oneOf(['horizontal', 'vertical'])
};

export default BySeverity;
